-- A partition key compared with an InitPlan's output or an enclosing
-- query's column prunes during each scan (PARTTARGET_EXEC): EXPLAIN ANALYZE
-- lists every member and marks those no scan reached (never executed); a
-- null value reaches none. An equality with an InitPlan's output belongs
-- to an equivalence class and follows the scan's other conditions. A write
-- computes its uncorrelated scalar subqueries as InitPlans after its result
-- relations; a FROM-less InitPlan counts its one row.
CREATE TABLE pt612 (id int, v int) PARTITION BY RANGE (id);
CREATE TABLE pt612_1 PARTITION OF pt612 FOR VALUES FROM (1) TO (10);
CREATE TABLE pt612_2 PARTITION OF pt612 FOR VALUES FROM (10) TO (20);
CREATE TABLE pt612_3 PARTITION OF pt612 FOR VALUES FROM (20) TO (30);
INSERT INTO pt612 SELECT g, g FROM generate_series(1, 29) g;
CREATE TABLE o612 (k int);
INSERT INTO o612 VALUES (5), (15);
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT * FROM pt612 WHERE id = (SELECT 15);
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT * FROM pt612 WHERE id = (SELECT 150);
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT * FROM pt612 WHERE id < (SELECT 12);
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT * FROM pt612 WHERE id = (SELECT max(k) FROM o612);
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT * FROM pt612 WHERE id IN (1, (SELECT 25));
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT * FROM pt612 WHERE id = (SELECT NULL::int);
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT (SELECT max(v) FROM pt612 WHERE pt612.id = o612.k) FROM o612;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT (SELECT count(*) FROM pt612 WHERE pt612.id > o612.k) FROM o612;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT count(*) FROM pt612 WHERE id = (SELECT 3) AND v > 0;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT * FROM pt612 WHERE id = (SELECT 15)::bigint;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) UPDATE pt612 SET v = 0 WHERE id = (SELECT 15);
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) DELETE FROM pt612 WHERE id = (SELECT 25);
SELECT * FROM pt612 WHERE id = (SELECT 15);
SELECT (SELECT max(v) FROM pt612 WHERE pt612.id = o612.k) FROM o612;
SELECT * FROM pt612 ORDER BY id;
CREATE TABLE p612 (id int, v int, w text);
INSERT INTO p612 SELECT g, g, g::text FROM generate_series(1, 29) g;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT * FROM p612 WHERE id = (SELECT 15);
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT (SELECT 15), * FROM o612;
EXPLAIN (COSTS OFF) SELECT * FROM p612 WHERE id = (SELECT 3) AND v > 0;
EXPLAIN (COSTS OFF) SELECT * FROM p612 WHERE id < (SELECT 3) AND v > 0;
EXPLAIN (COSTS OFF) SELECT * FROM p612 WHERE id = (SELECT 3) AND v = (SELECT 4) AND w > 'a';
EXPLAIN (COSTS OFF) SELECT * FROM p612 WHERE v = (SELECT 4) AND id = (SELECT 3);
EXPLAIN (COSTS OFF) SELECT * FROM p612 WHERE (SELECT 3) = id AND v > 0;
EXPLAIN (COSTS OFF) UPDATE p612 SET v = 0 WHERE id = (SELECT 15);
EXPLAIN (COSTS OFF) DELETE FROM p612 WHERE id = (SELECT max(k) FROM o612);
EXPLAIN (COSTS OFF) DELETE FROM p612 WHERE id > (SELECT max(k) FROM o612) AND v = 1;
EXPLAIN (COSTS OFF) UPDATE p612 SET v = (SELECT max(k) FROM o612) WHERE id = 3;
EXPLAIN (VERBOSE, COSTS OFF) UPDATE p612 SET v = (SELECT max(k) FROM o612) WHERE id = (SELECT 3);
EXPLAIN (COSTS OFF) UPDATE pt612 SET v = 0 WHERE id = (SELECT 15);
UPDATE p612 SET v = (SELECT max(k) FROM o612) WHERE id = (SELECT 3);
SELECT * FROM p612 WHERE id < 5 ORDER BY id;
